"""Do exactly what is_unique() does.

    Args:
        x ([list]): The list you want to test

    Returns:
        [bool]: True if every element in the list occurs only once
    """
def is_unique_bis(x: Any) -> object {
    return (len(`set(x)) == len(x));
}

